import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";

const Register = () => {
  const [formData, setFormData] = useState({
    nome: "",
    email: "",
    morada: "",
    contacto: "",
    senha: "",
  });

  const [message, setMessage] = useState({ text: "", type: "" }); // {text, type}
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage({ text: "", type: "" }); // Resetar mensagem

    try {
      const response = await fetch("http://localhost:5000/alunos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          nome: formData.nome,
          email: formData.email,
          morada: formData.morada,
          contacto: formData.contacto,
          senha: formData.senha,
          tipo: "Aluno",
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setMessage({
          text: "Registo realizado com sucesso! Redirecionando para login...",
          type: "success",
        });
        setTimeout(() => navigate("/login"), 2000);
      } else {
        // Verifica se o erro é devido a e-mail duplicado (status 409)
        if (response.status === 409) {
          setMessage({
            text: "Este e-mail já está registado. Por favor, tente outro.",
            type: "danger",
          });
        } else {
          setMessage({
            text:
              data.message || "Erro ao realizar o registo. Tente novamente.",
            type: "danger",
          });
        }
      }
    } catch (error) {
      setMessage({
        text: "Erro na conexão com o servidor. Tente mais tarde.",
        type: "danger",
      });
    }
  };

  return (
    <div className="container-fluid d-flex justify-content-center align-items-center min-vh-100 bg-light">
      <div className="card p-4 shadow" style={{ width: "350px" }}>
        <h2 className="text-center mb-4">Registo</h2>

        {/* Mensagem de erro/sucesso */}
        {message.text && (
          <div className={`alert alert-${message.type}`}>{message.text}</div>
        )}

        <form onSubmit={handleSubmit}>
          {/* Campos do formulário (mantidos iguais) */}
          <div className="mb-3">
            <label className="form-label">Nome</label>
            <input
              type="text"
              name="nome"
              className="form-control"
              value={formData.nome}
              onChange={handleChange}
              required
            />
          </div>
          <div className="mb-3">
            <label className="form-label">E-mail</label>
            <input
              type="email"
              name="email"
              className="form-control"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>
          <div className="mb-3">
            <label className="form-label">Morada</label>
            <input
              type="text"
              name="morada"
              className="form-control"
              value={formData.morada}
              onChange={handleChange}
              required
            />
          </div>
          <div className="mb-3">
            <label className="form-label">Contacto</label>
            <input
              type="text"
              name="contacto"
              className="form-control"
              value={formData.contacto}
              onChange={handleChange}
              required
            />
          </div>
          <div className="mb-3">
            <label className="form-label">Senha</label>
            <input
              type="password"
              name="senha"
              className="form-control"
              value={formData.senha}
              onChange={handleChange}
              required
            />
          </div>
          <button type="submit" className="btn btn-primary w-100">
            Registar
          </button>
        </form>

        <p className="text-center mt-3">
          Já tem uma conta? <a href="/login">Login</a>
        </p>
      </div>
    </div>
  );
};

export default Register;
